begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok(not has_table_privilege('authenticated','public.issued_documents','SELECT,INSERT,UPDATE,DELETE'),'Snapshot table is not a raw endpoint');
select ok(not has_table_privilege('authenticated','public.document_sequences','SELECT,INSERT,UPDATE,DELETE'),'Number allocator is private');
select ok(not has_table_privilege('carrier_documents','public.issued_documents','UPDATE,DELETE'),'Issuance owner cannot overwrite or delete originals');
select ok(not has_table_privilege('carrier_documents','public.financial_events','INSERT,UPDATE,DELETE') and not has_table_privilege('carrier_documents','public.journal_lines','INSERT,UPDATE,DELETE'),'Issuance cannot post money');
select ok(not pg_has_role('postgres','carrier_documents','SET') and not has_schema_privilege('carrier_documents','public','CREATE'),'Temporary migration privilege revoked');
select ok(not has_function_privilege('anon','public.issue_document(uuid,integer,jsonb)','EXECUTE'),'Anonymous issuance denied');
select ok(not has_function_privilege('authenticated','private.document_access(uuid)','EXECUTE'),'Private source authorization helper is closed');
select ok((select bool_and(prosecdef and proconfig @> array['search_path=""']) from pg_proc where oid in('public.issue_document(uuid,integer,jsonb)'::regprocedure,'public.get_issued_document(uuid)'::regprocedure)),'Document definers pin search paths');
select ok(has_function_privilege('carrier_documents','private.current_staff(boolean)','EXECUTE') and has_function_privilege('carrier_documents','public.prepare_output(text,text,uuid,jsonb,text[],jsonb,uuid,uuid,integer)','EXECUTE'),'Issuance owner can invoke narrowly granted security helpers');
select set_config('request.jwt.claims','{}',true);
set local role authenticated;
select throws_ok($$select public.issue_document(gen_random_uuid(),0,'{}')$$,'42501','FORBIDDEN','Issuance requires live staff');
select throws_ok($$select public.get_issued_document(gen_random_uuid())$$,'42501','FORBIDDEN','Snapshot retrieval requires live staff');
select throws_ok($$select public.list_issued_documents()$$,'42501','FORBIDDEN','Document listing requires live staff');
reset role;
select * from finish();
rollback;
